void Solver::rephase() {
    if (rephases == 0) {
        // First rephase: reset to local best phases
        for (int i = 1; i <= vars; i++) 
            saved[i] = local_best[i];
    } else if (rephases == 1) {
        // Second rephase: invert local best phases
        for (int i = 1; i <= vars; i++) 
            saved[i] = -local_best[i];
    } else {
        // Subsequent rephases: random phases
        for (int i = 1; i <= vars; i++) 
            saved[i] = rand() % 2 ? 1 : -1;
    }

    rephases++;
    threshold *= 0.95;  // Slower decay to be less aggressive
    rephase_limit += 4096;  // Smaller increment for more frequent rephases
}
